    // 任务看板：五列状态看板，任务由真实 DSH 智能体会话执行，支持 cron 定时。

const BOARD_COLUMNS = [
  { id: 'planned', label: '待规划', hint: '尚未就绪的任务' },
  { id: 'todo', label: '待办', hint: '就绪、等待执行' },
  { id: 'running', label: '进行中', hint: '智能体正在执行' },
  { id: 'done', label: '已完成', hint: '正常完成的任务' },
  { id: 'failed', label: '已失败', hint: '出错或中断' },
]

const boardUi = (() => {
  let state = { open: false, detailId: null }
  const listeners = new Set()
  return {
    getSnapshot: () => state,
    subscribe(listener) { listeners.add(listener); return () => listeners.delete(listener) },
    toggle() { state = { ...state, open: !state.open, detailId: state.open ? null : state.detailId }; listeners.forEach((fn) => fn()) },
    openDetail(id) { state = { ...state, detailId: id }; listeners.forEach((fn) => fn()) },
    closeDetail() { state = { ...state, detailId: null }; listeners.forEach((fn) => fn()) },
  }
})()

// 看板卡片长按拖动：pending（按住未松开）→ dragging（跟随指针 + 目标栏高亮）。
// 拖放结果由 TaskBoardPanel 异步提交 PATCH 后刷新轮询源（宿主持久化到 tasks.json）。
const boardDragUi = (() => {
  let state = { dragging: null, over: null, x: 0, y: 0, droppedAt: 0 }
  const listeners = new Set()
  const notify = () => listeners.forEach((fn) => fn())
  return {
    getSnapshot: () => state,
    subscribe(listener) { listeners.add(listener); return () => listeners.delete(listener) },
    start(id, title, x, y) { state = { dragging: { id, title }, over: null, x, y, droppedAt: 0 }; notify() },
    move(x, y, over) {
      if (state.dragging === null) return
      if (state.x === x && state.y === y && state.over === over) return
      state = { ...state, x, y, over }
      notify()
    },
    end() {
      if (state.dragging === null) return
      state = { dragging: null, over: null, x: 0, y: 0, droppedAt: Date.now() }
      notify()
    },
    cancel() { state = { dragging: null, over: null, x: 0, y: 0, droppedAt: 0 }; notify() },
  }
})()

function formatTime(ms) {
  if (!ms) return '—'
  const date = new Date(ms)
  const pad = (n) => String(n).padStart(2, '0')
  return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())} ${pad(date.getHours())}:${pad(date.getMinutes())}`
}

function TaskBoardTrigger(props) {
  const boardState = useExternal(boardUi, (state) => state)
  const settings = useExternal(runtimeRefs.settings, (state) => state)
  const enabled = settings?.taskboard?.enabled !== false
  const wide = props.wide !== false
  if (!enabled) return null
  return React.createElement('button', {
    type: 'button',
    className: `wsh-sidebar-action wsh-surface${wide ? '' : ' wsh-sidebar-action-rail'}`,
    title: '任务看板：规划、执行与定时任务',
    'aria-label': '任务看板',
    onClick: () => boardUi.toggle(),
    'aria-pressed': boardState.open,
  },
    wide
      ? React.createElement(React.Fragment, null,
        React.createElement('span', { className: 'wsh-label' }, '任务看板'),
        boardState.open ? React.createElement('span', { className: 'wsh-tag live' }, 'OPEN') : null)
      : React.createElement('span', { className: 'wsh-sidebar-action-icon', 'aria-hidden': 'true' }, '▦'))
}

function TaskColumn({ column, tasks, live, onRun, onCard, onDropColumn, overColumn }) {
  const list = tasks.filter((task) => task.status === column.id)
  // 进行中列：自动展示当前运行中的对话（不与任务卡片重复）。
  const liveRows = column.id === 'running' ? (live ?? []) : []
  const count = list.length + liveRows.length
  return React.createElement('section', { className: `wsh-column${overColumn === column.id ? ' drag-over' : ''}`, 'data-col': column.id },
    React.createElement('div', { className: 'wsh-column-head' },
      React.createElement('span', { className: 'wsh-dot' }),
      React.createElement('span', { className: 'wsh-label' }, column.label),
      React.createElement('span', { className: 'wsh-column-count' }, String(count).padStart(2, '0'))),
    React.createElement('div', { className: 'wsh-column-body' },
      list.map((task) => React.createElement(TaskCard, { key: task.id, task, onRun, onCard, onDropColumn })),
      liveRows.map((row) => React.createElement(LiveCard, { key: `live-${row.sessionId}`, live: row })),
      column.id === 'planned' ? React.createElement(AddTaskCard, null) : null))
}

// 运行中的对话卡片：自动上板、自动消失，点击跳转会话。
function LiveCard({ live }) {
  return React.createElement('div', {
    className: 'wsh-task-card live',
    onClick: () => openSession(live.sessionId),
    role: 'button',
    title: live.preview,
  },
    React.createElement('div', { className: 'wsh-task-title' }, live.title),
    React.createElement('div', { className: 'wsh-task-meta' },
      React.createElement('span', { className: `wsh-tag${live.status === 'running' ? ' live' : ''}` }, live.status === 'running' ? '执行中' : '对话就绪'),
      live.preset ? React.createElement('span', { className: 'wsh-hint' }, live.preset) : null,
      live.cwd ? React.createElement('span', { className: 'wsh-hint', style: { overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap', maxWidth: 90 } }, live.cwd) : null),
    live.preview ? React.createElement('div', { className: 'wsh-task-preview' }, live.preview) : null,
    React.createElement('div', { className: 'wsh-task-actions' },
      React.createElement('button', {
        className: 'wsh-btn mini primary',
        onClick: (event) => { event.stopPropagation(); openSession(live.sessionId) },
      }, '打开会话')))
}

function TaskCard({ task, onRun, onCard, onDropColumn }) {
  // 长按（约 260ms 不动）后开始拖动；短击仍打开详情，拖动结束抑制随后的 click。
  const dragRef = React.useRef(null)
  const suppressClickRef = React.useRef(0)
  const columnAt = (x, y) => {
    const element = document.elementFromPoint(x, y)
    const column = element?.closest?.('[data-col]')
    // 「进行中」只能通过「执行」按钮进入，不作为拖放目标。
    if (!column || column.dataset.col === 'running') return null
    return column.dataset.col
  }
  const startDrag = (event) => {
    if (event.button !== 0) return
    if (event.target.closest('button')) return
    if (dragRef.current !== null) return
    const drag = { phase: 'pending', timer: null }
    dragRef.current = drag
    const begin = () => {
      if (dragRef.current !== drag) return
      // pointer 可能已经抬起：只读当前按键状态无法可靠判断，改用 short interval 检查
      drag.phase = 'dragging'
      boardDragUi.start(task.id, task.title, event.clientX, event.clientY)
      document.body.classList.add('wsh-dragging-task')
    }
    const onPointerMove = (moveEvent) => {
      if (dragRef.current !== drag) return
      if (drag.phase === 'pending') return
      boardDragUi.move(moveEvent.clientX, moveEvent.clientY, columnAt(moveEvent.clientX, moveEvent.clientY))
    }
    const onPointerUp = () => {
      if (dragRef.current !== drag) return
      const wasDragging = drag.phase === 'dragging'
      clearTimeout(drag.timer)
      window.removeEventListener('pointermove', onPointerMove)
      window.removeEventListener('pointerup', onPointerUp)
      window.removeEventListener('pointercancel', onPointerUp)
      document.body.classList.remove('wsh-dragging-task')
      dragRef.current = null
      if (wasDragging) {
        const over = boardDragUi.getSnapshot().over
        boardDragUi.end()
        suppressClickRef.current = Date.now()
        if (over && over !== task.status) onDropColumn(task.id, over)
      }
    }
    drag.timer = setTimeout(begin, 260)
    window.addEventListener('pointermove', onPointerMove)
    window.addEventListener('pointerup', onPointerUp)
    window.addEventListener('pointercancel', onPointerUp)
  }
  return React.createElement('div', {
    className: `wsh-task-card${task.status === 'running' ? ' running' : ''}`,
    onClick: () => { if (Date.now() - suppressClickRef.current < 400) return; onCard(task.id) },
    onPointerDown: startDrag,
    role: 'button',
    title: '点击查看详情；按住约半秒后拖动可换栏',
  },
    React.createElement('div', { className: 'wsh-task-title' }, task.title),
    React.createElement('div', { className: 'wsh-task-meta' },
      task.cronEnabled && task.cron ? React.createElement('span', { className: 'wsh-task-cron', title: `下次执行 ${formatTime(task.nextRunAt)}` }, `⏱ ${task.cron}`) : null,
      task.sessionId ? React.createElement('span', { className: 'wsh-tag live' }, '会话已挂载') : null,
      task.status === 'running' ? React.createElement('span', { className: 'wsh-tag live' }, '执行中') : null),
    React.createElement('div', { className: 'wsh-task-actions' },
      (task.status === 'planned' || task.status === 'todo' || task.status === 'failed' || task.status === 'done')
        ? React.createElement('button', {
          className: 'wsh-btn primary mini',
          onClick: (event) => { event.stopPropagation(); onRun(task.id) },
        }, task.status === 'done' || task.status === 'failed' ? '重跑' : '执行')
        : null,
      React.createElement('span', { className: 'wsh-hint', style: { marginLeft: 'auto' } }, formatTime(task.lastRunAt))))
}

function AddTaskCard() {
  const [open, setOpen] = React.useState(false)
  const [title, setTitle] = React.useState('')
  const [busy, setBusy] = React.useState(false)
  const tasksSource = runtimeRefs.tasks
  if (!open) {
    return React.createElement('button', { className: 'wsh-add-task', onClick: () => setOpen(true) }, '+ 新建任务')
  }
  const submit = async () => {
    if (!title.trim() || busy) return
    setBusy(true)
    try {
      await api('POST', '/tasks', { title: title.trim() })
      setTitle('')
      setOpen(false)
      await tasksSource.refresh()
    } finally {
      setBusy(false)
    }
  }
  return React.createElement('div', { className: 'wsh-task-card' },
    React.createElement('input', {
      autoFocus: true, type: 'text', placeholder: '任务标题', value: title,
      style: { width: '100%', background: '#101216', border: '1px solid var(--w-line)', padding: '5px 8px' },
      onChange: (event) => setTitle(event.target.value),
      onKeyDown: (event) => { if (event.key === 'Enter') submit() },
    }),
    React.createElement('div', { className: 'wsh-task-actions' },
      React.createElement('button', { className: 'wsh-btn primary mini', onClick: submit, disabled: busy || !title.trim() }, '创建'),
      React.createElement('button', { className: 'wsh-btn mini', onClick: () => setOpen(false) }, '取消')))
}

// 常用定时表达式：让用户直接选固定时间/区间，而非手写 cron。
const CRON_PRESETS = [
  { label: '每 5 分钟', value: '*/5 * * * *' },
  { label: '每 30 分钟', value: '*/30 * * * *' },
  { label: '每小时', value: '0 * * * *' },
  { label: '每 2 小时', value: '0 */2 * * *' },
  { label: '每天 00:00', value: '0 0 * * *' },
  { label: '每天 09:00', value: '0 9 * * *' },
  { label: '每天 12:00', value: '0 12 * * *' },
  { label: '每天 18:00', value: '0 18 * * *' },
  { label: '工作日 08:30', value: '30 8 * * 1-5' },
  { label: '每周一 09:00', value: '0 9 * * 1' },
  { label: '每月 1 日 09:00', value: '0 9 1 * *' },
]

function TaskDetail({ task, onClose }) {
  const [draft, setDraft] = React.useState(null)
  const [busy, setBusy] = React.useState(false)
  const [error, setError] = React.useState(null)
  const [cronPreview, setCronPreview] = React.useState(null)
  const [options, setOptions] = React.useState({ dirs: [], presets: [], loaded: false })
  const current = draft ?? task
  const tasksSource = runtimeRefs.tasks
  const dirList = options.dirs ?? []

  // 工作目录与预设选择只在打开详情时读取一次。
  React.useEffect(() => {
    let cancelled = false
    api('GET', '/task-options').then((data) => {
      if (!cancelled) setOptions({ dirs: Array.isArray(data?.dirs) ? data.dirs : [], presets: Array.isArray(data?.presets) ? data.presets : [], loaded: true })
    }).catch(() => { if (!cancelled) setOptions((prev) => ({ ...prev, loaded: true })) })
    return () => { cancelled = true }
  }, [task.id])

  const field = (key, value) => setDraft({ ...(draft ?? task), [key]: value })

  const save = async () => {
    if (busy) return
    setBusy(true)
    setError(null)
    try {
      await api('PATCH', `/tasks/${task.id}`, { patch: draft })
      setDraft(null)
      await tasksSource.refresh()
    } catch (cause) {
      setError(String(cause?.message ?? cause))
    } finally {
      setBusy(false)
    }
  }

  const run = async () => {
    if (busy) return
    setBusy(true)
    setError(null)
    try {
      await api('POST', '/tasks/run', { id: task.id })
      await tasksSource.refresh()
      onClose()
    } catch (cause) {
      setError(String(cause?.message ?? cause))
    } finally {
      setBusy(false)
    }
  }

  const cancel = async () => {
    if (busy) return
    setBusy(true)
    setError(null)
    try {
      await api('POST', '/tasks/cancel', { id: task.id })
      await tasksSource.refresh()
    } catch (cause) {
      setError(String(cause?.message ?? cause))
    } finally {
      setBusy(false)
    }
  }

  const remove = async () => {
    if (busy) return
    setBusy(true)
    try {
      await api('DELETE', `/tasks/${task.id}`)
      await tasksSource.refresh()
      onClose()
    } catch (cause) {
      setError(String(cause?.message ?? cause))
    } finally {
      setBusy(false)
    }
  }

  const previewCron = async () => {
    try {
      const data = await api('GET', '/cron/next', undefined, { expr: current.cron })
      setCronPreview(data.next ? formatTime(data.next) : '（无未来命中）')
    } catch (cause) {
      setCronPreview(`无效表达式：${String(cause?.message ?? cause)}`)
    }
  }

  return React.createElement('div', { className: 'wsh-detail', onClick: (event) => { if (event.target === event.currentTarget) onClose() } },
    React.createElement('div', { className: 'wsh-detail-card wsh-surface' },
      React.createElement('h3', null, current.title),
      React.createElement('label', null,
        React.createElement('span', { className: 'wsh-label' }, '任务指令（发送给智能体）'),
        React.createElement('textarea', { rows: 4, value: current.prompt ?? '', onChange: (event) => field('prompt', event.target.value) })),
      React.createElement('label', null,
        React.createElement('span', { className: 'wsh-label' }, '描述'),
        React.createElement('textarea', { rows: 2, value: current.description ?? '', onChange: (event) => field('description', event.target.value) })),
      React.createElement('div', { className: 'wsh-settings-row', style: { alignItems: 'flex-start' } },
        React.createElement('span', null,
          React.createElement('strong', null, '定时执行'),
          React.createElement('small', { style: { display: 'block', color: 'var(--w-muted)' } }, '从常用时间中选择，或选「自定义」手写 cron')),
        React.createElement('label', { className: 'wsh-settings-field' },
          React.createElement('input', { className: 'wsh-check', type: 'checkbox', checked: current.cronEnabled !== false, onChange: (event) => field('cronEnabled', event.target.checked) }),
          React.createElement('strong', null, '启用'))),
      React.createElement('div', { className: 'wsh-task-form-grid' },
        React.createElement('select', {
          value: CRON_PRESETS.some((item) => item.value === (current.cron ?? '')) ? (current.cron ?? '') : (current.cron ?? '').trim() ? '__custom__' : '',
          onChange: (event) => {
            if (event.target.value === '__custom__') { field('cron', current.cron ?? ''); return }
            field('cron', event.target.value)
            setCronPreview(null)
          },
          'aria-label': '常用定时时间',
        },
          React.createElement('option', { value: '' }, '（不定时）'),
          CRON_PRESETS.map((item) => React.createElement('option', { key: item.value, value: item.value }, item.label)),
          React.createElement('option', { value: '__custom__' }, '自定义…')),
        React.createElement('input', {
          type: 'text', value: current.cron ?? '', placeholder: '0 23 * * *（分 时 日 月 周）',
          onChange: (event) => field('cron', event.target.value),
          onBlur: () => { if ((current.cron ?? '').trim()) previewCron() },
          'aria-label': '自定义 cron 表达式',
        }),
        React.createElement('button', { type: 'button', className: 'wsh-btn mini', onClick: previewCron, disabled: !(current.cron ?? '').trim() }, '预览下次执行'),
        cronPreview ? React.createElement('span', { className: 'wsh-hint wsh-task-form-full' }, `下次执行：${cronPreview}`) : null),
      React.createElement('div', { className: 'wsh-settings-row' },
        React.createElement('span', { className: 'wsh-label' }, '状态'),
        React.createElement('select', {
          value: current.status,
          onChange: (event) => field('status', event.target.value),
          style: { background: '#101216', border: '1px solid var(--w-line)', padding: '3px 8px' },
        },
          BOARD_COLUMNS.filter((column) => column.id !== 'running').map((column) => React.createElement('option', { key: column.id, value: column.id }, column.label)))),
      React.createElement('div', { className: 'wsh-settings-row', style: { alignItems: 'flex-start', flexDirection: 'column', gap: 6 } },
        React.createElement('span', null,
          React.createElement('strong', null, '预设'),
          React.createElement('small', { style: { display: 'block', color: 'var(--w-muted)' } }, '执行任务时挂载的智能体角色配置（对应 harness 的 agent preset）。留空 = 使用 DSH 当前默认预设。')),
        React.createElement('select', {
          value: options.presets.some((item) => item.id === (current.preset ?? '')) ? (current.preset ?? '') : (current.preset ?? '').trim() ? '__custom__' : '',
          onChange: (event) => { if (event.target.value === '__custom__') { field('preset', current.preset ?? ''); return } field('preset', event.target.value || '') },
          style: { background: '#101216', border: '1px solid var(--w-line)', padding: '3px 8px' },
          'aria-label': '选择预设',
        },
          React.createElement('option', { value: '' }, '（默认预设）'),
          options.presets.map((item) => React.createElement('option', { key: item.id, value: item.id }, `${item.name}（${item.id}）`)),
          React.createElement('option', { value: '__custom__' }, '自定义…')),
        React.createElement('input', {
          type: 'text', value: current.preset ?? '', placeholder: '自定义预设 id',
          onChange: (event) => field('preset', event.target.value),
          style: { background: '#101216', border: '1px solid var(--w-line)', padding: '3px 8px' },
          'aria-label': '自定义预设 id',
        })),
      React.createElement('div', { className: 'wsh-settings-row', style: { alignItems: 'flex-start', flexDirection: 'column', gap: 6 } },
        React.createElement('span', null,
          React.createElement('strong', null, '工作目录'),
          React.createElement('small', { style: { display: 'block', color: 'var(--w-muted)' } }, '执行任务的智能体起始文件夹：从 DSH 已注册的工作区中选择，或选「自定义」手动输入。')),
        React.createElement('select', {
          value: dirList.includes(current.cwd ?? '') ? (current.cwd ?? '') : (current.cwd ?? '').trim() ? '__custom__' : '',
          onChange: (event) => { if (event.target.value === '__custom__') { field('cwd', current.cwd ?? ''); return } field('cwd', event.target.value || '') },
          style: { background: '#101216', border: '1px solid var(--w-line)', padding: '3px 8px' },
          'aria-label': '选择工作目录',
        },
          React.createElement('option', { value: '' }, '（使用当前工作区）'),
          dirList.map((dir) => React.createElement('option', { key: dir, value: dir }, dir)),
          React.createElement('option', { value: '__custom__' }, '自定义…')),
        React.createElement('input', {
          type: 'text', value: current.cwd ?? '', placeholder: '自定义绝对路径',
          onChange: (event) => field('cwd', event.target.value),
          style: { background: '#101216', border: '1px solid var(--w-line)', padding: '3px 8px' },
          'aria-label': '自定义工作目录',
        })),
      current.lastResult ? React.createElement('div', null,
        React.createElement('span', { className: 'wsh-label' }, '上次执行结果'),
        React.createElement('div', { className: 'wsh-result' }, current.lastResult)) : null,
      current.sessionId ? React.createElement('div', null,
        React.createElement('span', { className: 'wsh-label' }, '执行会话'),
        React.createElement('div', null,
          React.createElement('span', { className: 'wsh-link', onClick: () => openSession(current.sessionId) }, `打开会话 ${current.sessionId}`))) : null,
      error ? React.createElement('div', { className: 'wsh-hint', style: { color: 'var(--w-red-hot)' } }, error) : null,
      React.createElement('div', { className: 'wsh-task-actions', style: { justifyContent: 'flex-end' } },
        current.status === 'running'
          ? React.createElement('button', { className: 'wsh-btn danger', onClick: cancel, disabled: busy }, busy ? '停止中…' : '停止执行')
          : React.createElement('button', { className: 'wsh-btn primary', onClick: run, disabled: busy }, '执行'),
        React.createElement('button', { className: 'wsh-btn', onClick: save, disabled: busy || draft === null }, '保存修改'),
        React.createElement('button', { className: 'wsh-btn danger', onClick: remove, disabled: busy || current.status === 'running' }, current.status === 'running' ? '执行中不可删' : '删除'),
        React.createElement('button', { className: 'wsh-btn', onClick: onClose }, '关闭'))))
}

function TaskBoardPanel() {
  const ui = useExternal(boardUi, (state) => state)
  const drag = useExternal(boardDragUi, (state) => state)
  const settings = useExternal(runtimeRefs.settings, (state) => state)
  const boardData = useExternal(runtimeRefs.tasks, (state) => state)
  const [error, setError] = React.useState(null)
  const tasks = boardData?.tasks ?? []
  const live = boardData?.live ?? []

  // 全局 Escape 关闭（焦点可能在面板外，需 window 级监听；仅打开时响应）。
  React.useEffect(() => {
    const onKey = (event) => {
      if (event.key !== 'Escape') return
      if (boardDragUi.getSnapshot().dragging !== null) boardDragUi.cancel()
      else if (boardUi.getSnapshot().open) boardUi.toggle()
    }
    window.addEventListener('keydown', onKey)
    return () => window.removeEventListener('keydown', onKey)
  }, [])

  // 拖动换栏：PATCH 状态后刷新轮询源（宿主持久化 tasks.json，重启后保留）。
  const moveTaskStatus = (id, status) => {
    setError(null)
    api('PATCH', `/tasks/${id}`, { patch: { status } })
      .then(() => runtimeRefs.tasks.refresh())
      .catch((cause) => setError(`拖动换栏失败：${String(cause?.message ?? cause)}`))
  }

  if (!ui.open) return null
  if (settings?.taskboard?.enabled === false) {
    return React.createElement('div', { className: 'wsh-overlay-root wsh-centered wsh-surface', onClick: () => boardUi.toggle() },
      React.createElement('div', { className: 'wsh-overlay-panel', style: { width: 'auto', height: 'auto', padding: 24 } },
        React.createElement('p', null, '任务看板已在「设置 > 插件配置」中停用。'),
        React.createElement('button', { className: 'wsh-btn', onClick: () => boardUi.toggle() }, '关闭')))
  }
  const active = ui.detailId ? (tasks ?? []).find((task) => task.id === ui.detailId) : undefined
  // 过滤：已有任务卡片挂载的会话不再重复显示。
  const ownedSessionIds = new Set((tasks ?? []).map((task) => task.sessionId).filter(Boolean))
  const liveRows = (live ?? []).filter((row) => !ownedSessionIds.has(row.sessionId))
  const serviceError = runtimeRefs.tasks.getError()
  const reload = async () => {
    setError(null)
    await runtimeRefs.tasks.refresh().catch(() => {})
  }
  const run = async (id) => {
    setError(null)
    try {
      await api('POST', '/tasks/run', { id })
      await runtimeRefs.tasks.refresh()
    } catch (cause) {
      setError(String(cause?.message ?? cause))
    }
  }
  // 全局 Escape 与点击背景关闭（焦点可能在面板外，需 window 级监听）。
  return React.createElement('div', {
    className: 'wsh-overlay-root',
    role: 'dialog',
    'aria-label': '任务看板',
    onClick: (event) => { if (Date.now() - boardDragUi.getSnapshot().droppedAt < 400) return; if (event.target === event.currentTarget) boardUi.toggle() },
  },
    React.createElement('div', { className: 'wsh-overlay-panel wsh-taskboard-panel wsh-surface', style: { position: 'relative' } },
      React.createElement('div', { className: 'wsh-overlay-head' },
        React.createElement('h2', null, '任务看板 TASK BOARD'),
        React.createElement('span', { className: 'wsh-tag', style: { marginLeft: 4 } }, 'LIVE + SCHEDULED'),
        drag.dragging ? React.createElement('span', { className: 'wsh-tag amber' }, '拖动卡片到目标栏（进行中由“执行”进入）') : null,
        React.createElement('span', { className: 'wsh-spacer' }),
        error ? React.createElement('span', { className: 'wsh-hint', style: { color: 'var(--w-red-hot)' } }, error) : null,
        React.createElement('button', { className: 'wsh-btn mini', onClick: reload }, '刷新'),
        React.createElement('button', { className: 'wsh-btn', onClick: () => boardUi.toggle() }, '关闭')),
      boardData === null ? React.createElement('div', { className: 'wsh-overlay-body' },
        React.createElement('div', { className: 'wsh-tree-empty' }, '任务服务不可用（请重启 dsh web 以加载插件宿主半边）。'),
        serviceError ? React.createElement('div', { className: 'wsh-tree-empty' }, serviceError) : null)
        : React.createElement('div', { className: 'wsh-overlay-body' },
          React.createElement('div', { className: 'wsh-board' },
            BOARD_COLUMNS.map((column) => React.createElement(TaskColumn, {
              key: column.id, column, tasks: tasks ?? [], live: liveRows,
              onRun: run,
              onCard: (id) => boardUi.openDetail(id),
              onDropColumn: moveTaskStatus,
              overColumn: drag.over,
            })))),
      drag.dragging ? React.createElement('div', { className: 'wsh-task-ghost', style: { left: drag.x + 10, top: drag.y + 12 } }, drag.dragging.title) : null,
      active ? React.createElement(TaskDetail, { task: active, onClose: () => boardUi.closeDetail() }) : null))
}

// settingsStore / tasksSource 由 runtime.js 注入后引用（共享 runtimeRefs）。
function installTaskboard(ctx, settingsStore, tasksSource) {
  runtimeRefs.settings = settingsStore
  runtimeRefs.tasks = tasksSource
  const slots = ctx.get('slots')
  if (slots === undefined) return
  ctx.effect(() => slots.inject('sidebar.footer.action', () => slots.register({
    name: 'sidebar.footer.action',
    id: 'wishadel-taskboard',
    order: 40,
    label: '任务看板',
  }, TaskBoardTrigger)), 'wishadel: taskboard trigger')
  ctx.effect(() => slots.inject('shell.overlay', () => slots.register({
    name: 'shell.overlay',
    id: 'wishadel-taskboard-overlay',
    order: 20,
    label: '任务看板',
  }, TaskBoardPanel)), 'wishadel: taskboard overlay')
}
    //#endregion src/client/taskboard.js
    //#region src/client/sidebar-pin.js
    // 会话置顶（侧栏）：
// 宿主的「...」菜单没有扩展槽（rename/fork/archive 写死），行 DOM 也不携带会话 id。
// 方案：宿主导出 /wishadel/sessions-index（id↔标题）与 /wishadel/pinned（置顶列表）；
// 客户端给每个会话行注入置顶按钮（hover 显示，置顶后常驻红色），
// 并按组头把置顶行的 wrapper 移到组内顶部（DOM 重排 + MutationObserver 自愈，
// 行列表由宿主按 key 渲染，时间标签等更新不会串行）。

const pinState = (() => {
  let state = { ids: [], order: [], index: new Map(), ready: false }
  const listeners = new Set()
  const notify = () => listeners.forEach((fn) => fn())
  return {
    getSnapshot: () => state,
    subscribe(fn) { listeners.add(fn); return () => listeners.delete(fn) },
    setIds(ids) { state = { ...state, ids, ready: true }; notify() },
    setIndex(index, order) { state = { ...state, index, order: order ?? state.order }; notify() },
  }
})()

const PIN_SVG = '<svg width="12" height="12" viewBox="0 0 16 16" aria-hidden="true"><path d="M9.6 1.4l5 5c.2.2.2.5 0 .7l-2.2 2.2-.6 4.6c0 .2-.2.4-.4.4-.1 0-.2 0-.3-.1l-3-1.9-2.7 2.7c-.2.2-.5.2-.7 0L3.3 13.6c-.2-.2-.2-.5 0-.7l2.7-2.7-1.9-3c-.1-.1-.1-.2-.1-.3 0-.2.2-.4.4-.4l4.6-.6 2.2-2.2c.2-.2.5-.2.7 0z" fill="currentColor"/></svg>'

function sidebarRoot() {
  return document.querySelector('[data-wishadel-pane="sidebar"]') ?? document.body
}

// 行 → 会话 id：优先解析宿主「...」按钮 aria-label（会话“标题”的操作），
// 兜底用行内标题元素文本，再对照宿主索引。
// 注意排除我们自己注入的置顶按钮。
function rowIdOf(row) {
  const ell = [...row.querySelectorAll('button')].find((btn) => !btn.classList.contains('wsh-pin-btn'))
  const label = ell?.getAttribute('aria-label') ?? ''
  let match = /会话[“"]([^”"]+)[”"]的操作/.exec(label)
  let title = match ? match[1] : null
  if (title === null) {
    const titleEl = row.querySelector('[class*="title"]')
    title = titleEl ? titleEl.textContent.trim() : null
  }
  if (!title) return null
  return pinState.getSnapshot().index.get(title) ?? null
}

function isPinnedId(id) {
  return id !== null && pinState.getSnapshot().ids.includes(id)
}

function ensurePinButtons() {
  for (const row of document.querySelectorAll('[role="treeitem"]')) {
    if (String(row.className).includes('projectRow')) continue
    const ell = [...row.querySelectorAll('button')].find((btn) => !btn.classList.contains('wsh-pin-btn'))
    if (!ell) continue
    let btn = ell.parentElement.querySelector('.wsh-pin-btn')
    if (!btn) {
      btn = document.createElement('button')
      btn.type = 'button'
      btn.className = 'wsh-pin-btn'
      btn.title = '置顶 / 取消置顶'
      btn.setAttribute('aria-label', '置顶 / 取消置顶')
      btn.innerHTML = PIN_SVG
      btn.addEventListener('click', (event) => {
        event.stopPropagation()
        event.preventDefault()
        togglePin(rowIdOf(row))
      })
      ell.parentElement.insertBefore(btn, ell)
    }
    btn.classList.toggle('wsh-pinned', isPinnedId(rowIdOf(row)))
  }
}

async function togglePin(id) {
  if (!id) return
  const pinned = pinState.getSnapshot().ids.includes(id)
  if (pinned) {
    // 取消置顶：登记待归位，随后 applyPinOrder 按宿主最新序放回未置顶区
    if (!demoteQueue.includes(id)) demoteQueue.push(id)
  }
  try {
    const data = await api('POST', '/pinned', { sessionId: id, pinned: !pinned })
    pinState.setIds(data.ids ?? [])
  } catch { /* 宿主尚未更新路由时静默 */ }
}

// 取消置顶时登记的待归位会话 id：applyPinOrder 对其所在组的未置顶区按宿主序重排
const demoteQueue = []
function applyPinOrder() {
  const snapshot = pinState.getSnapshot()
  if (!snapshot.ready) return
  const pinnedSet = new Set(snapshot.ids)
  const containers = new Set()
  for (const row of document.querySelectorAll('[role="treeitem"]')) {
    const wrapper = row.parentElement
    if (wrapper && wrapper.parentElement) containers.add(wrapper.parentElement)
  }
  if (snapshot.ids.length > 0) {
    for (const container of containers) {
      // 第一遍：按组头分段收集置顶 wrapper
      const groups = []
      for (const child of [...container.children]) {
        const row = child.querySelector ? child.querySelector('[role="treeitem"]') : null
        if (!row) continue
        if (String(row.className).includes('projectRow')) { groups.push({ header: child, pinned: [] }); continue }
        if (groups.length === 0) continue
        const id = rowIdOf(row)
        if (id !== null && pinnedSet.has(id)) groups[groups.length - 1].pinned.push(child)
      }
      // 第二遍：每个组把置顶 wrapper 按置顶序插到组头之后
      for (const group of groups) {
        if (group.pinned.length === 0) continue
        const ordered = [...group.pinned].sort((a, b) => {
          const aId = rowIdOf(a.querySelector('[role="treeitem"]'))
          const bId = rowIdOf(b.querySelector('[role="treeitem"]'))
          return snapshot.ids.indexOf(aId) - snapshot.ids.indexOf(bId)
        })
        let anchor = group.header.nextElementSibling
        for (const wrapper of ordered) {
          if (anchor === wrapper) { anchor = anchor.nextElementSibling; continue }
          container.insertBefore(wrapper, anchor)
        }
      }
    }
  }
  // 第三遍：归位 —— 含待归位行的组，把未置顶区按宿主最新序重排
  const demoteSet = new Set(demoteQueue)
  if (demoteSet.size > 0) {
    const rankOf = (wrapper) => {
      const id = rowIdOf(wrapper.querySelector('[role="treeitem"]'))
      return id === null ? -1 : snapshot.order.indexOf(id)
    }
    for (const container of containers) {
      let header = null
      let lastPinned = null
      let groupUnpinned = []
      let hasDemote = false
      const flush = () => {
        if (!header || !hasDemote || groupUnpinned.length === 0) return
        const ordered = [...groupUnpinned].sort((a, b) => {
          const ra = rankOf(a)
          const rb = rankOf(b)
          if (ra < 0 && rb < 0) return 0
          if (ra < 0) return 1
          if (rb < 0) return -1
          return ra - rb
        })
        let anchor = (lastPinned ?? header).nextElementSibling
        for (const wrapper of ordered) {
          if (anchor === wrapper) { anchor = anchor.nextElementSibling; continue }
          container.insertBefore(wrapper, anchor)
        }
      }
      for (const child of [...container.children]) {
        const row = child.querySelector ? child.querySelector('[role="treeitem"]') : null
        if (!row) continue
        if (String(row.className).includes('projectRow')) {
          flush()
          header = child
          lastPinned = null
          groupUnpinned = []
          hasDemote = false
          continue
        }
        if (!header) continue
        const id = rowIdOf(row)
        if (id === null) continue
        if (pinnedSet.has(id)) { lastPinned = child; continue }
        groupUnpinned.push(child)
        if (demoteSet.has(id)) hasDemote = true
      }
      flush()
    }
    demoteQueue.length = 0
  }
}

async function refreshIndex() {
  try {
    const data = await api('GET', '/sessions-index')
    const map = new Map()
    const order = []
    for (const s of data.sessions ?? []) {
      if (typeof s?.title === 'string' && typeof s?.id === 'string') {
        map.set(s.title, s.id)
        order.push(s.id)
      }
    }
    pinState.setIndex(map, order)
  } catch { /* 宿主尚未更新路由时静默 */ }
}

function installSidebarPin(ctx) {
  let disposed = false
  let timer = null
  const run = () => {
    timer = null
    if (disposed) return
    ensurePinButtons()
    applyPinOrder()
  }
  const schedule = () => { if (timer === null) timer = setTimeout(run, 150) }

  const root = sidebarRoot()
  const observer = new MutationObserver(schedule)
  observer.observe(root, { childList: true, subtree: true })
  run()

  const unsubscribe = pinState.subscribe(() => schedule())
  refreshIndex()
  api('GET', '/pinned').then((data) => pinState.setIds(data.ids ?? [])).catch(() => {})
  const indexTimer = setInterval(() => refreshIndex(), 30000)

  ctx.effect(() => () => {
    disposed = true
    observer.disconnect()
    unsubscribe()
    clearInterval(indexTimer)
    if (timer !== null) clearTimeout(timer)
    for (const btn of document.querySelectorAll('.wsh-pin-btn')) btn.remove()
  }, 'wishadel: sidebar pin')
}
    //#endregion src/client/sidebar-pin.js
    //#region src/client/sidebar-nav.js
    // 侧栏键盘导航：补齐 rc.6 treeitem 的 roving tabindex 与常用方向键。
// 宿主行本身是 role=treeitem 但没有 tabindex/Arrow 导航；这里仅作用于
// Wishadel 标记的侧栏区域，不抢占输入框、菜单按钮和其他控件的按键。
// 新版 DSH 侧栏行已自带键盘处理：本补丁默认关闭（设置卡 superseded.sidebarNav 开启）。

function sidebarNavEnabled() {
  return wishadelSuperseded('sidebarNav')
}

function sidebarNavRoot() {
  return document.querySelector('[data-wishadel-pane="sidebar"]') ?? document.body
}

function navRows(root) {
  if (!root || typeof root.querySelectorAll !== 'function') return []
  return [...root.querySelectorAll('[role="treeitem"]')].filter((row) => {
    const rect = row.getBoundingClientRect()
    return rect.width > 0 && rect.height > 0 && getComputedStyle(row).visibility !== 'hidden'
  })
}

function isWorkspaceRow(row) {
  return String(row.className).includes('projectRow')
}

function syncRoving(root, active) {
  const rows = navRows(root)
  const selected = active ?? rows.find((row) => row.getAttribute('aria-selected') === 'true') ?? rows[0]
  for (const row of rows) {
    const value = row === selected ? '0' : '-1'
    if (row.getAttribute('tabindex') !== value) row.setAttribute('tabindex', value)
  }
}

function focusRow(root, row) {
  if (!row) return
  syncRoving(root, row)
  row.focus({ preventScroll: true })
  row.scrollIntoView({ block: 'nearest' })
}

function installSidebarNavigation(ctx) {
  let timer = null
  const root = sidebarNavRoot()
  const schedule = () => {
    if (timer !== null) return
    timer = setTimeout(() => {
      timer = null
      // 默认关闭：移除历史会话注入的 tabindex 后直接返回。
      if (!sidebarNavEnabled()) {
        for (const row of navRows(root)) row.removeAttribute('tabindex')
        return
      }
      syncRoving(root)
    }, 80)
  }
  const onFocusIn = (event) => {
    if (!sidebarNavEnabled()) return
    const target = event.target
    if (!(target instanceof Element)) return
    const row = target.closest('[role="treeitem"]')
    if (row && root.contains(row)) syncRoving(root, row)
  }
  const onKeyDown = (event) => {
    if (!sidebarNavEnabled()) return
    const target = event.target
    if (!(target instanceof Element)) return
    if (target.closest('input, textarea, select, button, [contenteditable="true"], [role="menu"]')) return
    const row = target.closest('[role="treeitem"]')
    if (!row || !root.contains(row)) return
    const rows = navRows(root)
    const index = rows.indexOf(row)
    if (index < 0) return
    let next = null
    if (event.key === 'ArrowDown') next = rows[index + 1] ?? rows[0]
    else if (event.key === 'ArrowUp') next = rows[index - 1] ?? rows[rows.length - 1]
    else if (event.key === 'Home') next = rows[0]
    else if (event.key === 'End') next = rows[rows.length - 1]
    else if (event.key === 'Enter' || event.key === ' ' || event.key === 'Spacebar') {
      event.preventDefault()
      row.focus({ preventScroll: true })
      row.click()
      return
    } else if (event.key === 'ArrowRight' && isWorkspaceRow(row)) {
      if (row.getAttribute('aria-expanded') !== 'true') {
        event.preventDefault()
        row.focus({ preventScroll: true })
        row.click()
        return
      }
      next = rows[index + 1] ?? row
    } else if (event.key === 'ArrowLeft') {
      if (isWorkspaceRow(row) && row.getAttribute('aria-expanded') === 'true') {
        event.preventDefault()
        row.focus({ preventScroll: true })
        row.click()
        return
      }
      for (let i = index - 1; i >= 0; i--) {
        if (isWorkspaceRow(rows[i])) { next = rows[i]; break }
      }
    }
    if (!next) return
    event.preventDefault()
    focusRow(root, next)
  }
  const observer = new MutationObserver(schedule)
  observer.observe(root, { childList: true, subtree: true, attributes: true, attributeFilter: ['aria-selected', 'aria-expanded'] })
  if (sidebarNavEnabled()) syncRoving(root)
  // 设置变化（开启/关闭）时即时同步 tabindex 状态。
  const unsubscribeSettings = runtimeRefs.settings?.subscribe?.(() => schedule()) ?? null
  document.addEventListener('focusin', onFocusIn, true)
  document.addEventListener('keydown', onKeyDown, true)
  ctx.effect(() => () => {
    observer.disconnect()
    if (unsubscribeSettings) unsubscribeSettings()
    document.removeEventListener('focusin', onFocusIn, true)
    document.removeEventListener('keydown', onKeyDown, true)
    if (timer !== null) clearTimeout(timer)
    for (const row of root.querySelectorAll('[role="treeitem"]')) row.removeAttribute('tabindex')
  }, 'wishadel: sidebar keyboard navigation')
}
    //#endregion src/client/sidebar-nav.js
    //#region src/client/session-files.js
    // 会话「文件」标签页：在对话/轨迹标签后注入「文件」标签，
// 展示当前会话工作区的 git 变更文件（本会话的改动），支持：
//  - 审查：展开该文件的 diff；
//  - 还原：丢弃该文件的改动（回到 HEAD / 删除未跟踪文件）；
//  - 认可：把当前变更标记为已认可，从列表隐藏；文件再次变化会重新出现。
// 会话定位：侧栏选中行标题 → 宿主 /sessions-index（id + cwd）。

const filesUi = (() => {
  let state = { open: false }
  const listeners = new Set()
  const notify = () => listeners.forEach((fn) => fn())
  return {
    getSnapshot: () => state,
    subscribe(fn) { listeners.add(fn); return () => listeners.delete(fn) },
    open() { if (!state.open) { state = { open: true }; notify() } },
    close() { if (state.open) { state = { open: false }; notify() } },
  }
})()

const sessionMetaStore = (() => {
  let state = { map: new Map(), ready: false }
  const listeners = new Set()
  const notify = () => listeners.forEach((fn) => fn())
  return {
    getSnapshot: () => state,
    subscribe(fn) { listeners.add(fn); return () => listeners.delete(fn) },
    setMap(map) { state = { map, ready: true }; notify() },
  }
})()

let lastResolvedRoot = null

async function refreshSessionMeta() {
  try {
    const data = await api('GET', '/sessions-index')
    const map = new Map()
    for (const s of data.sessions ?? []) {
      if (typeof s?.title === 'string' && typeof s?.id === 'string') {
        map.set(s.title, { id: s.id, cwd: typeof s.cwd === 'string' ? s.cwd : undefined })
      }
    }
    sessionMetaStore.setMap(map)
  } catch { /* 宿主尚未更新路由时静默 */ }
}

function selectedRowTitle() {
  const row = document.querySelector('[role="treeitem"][aria-selected="true"]')
  if (!row) return null
  const titleEl = row.querySelector('[class*="title"]')
  const text = titleEl ? titleEl.textContent.trim() : null
  return text || null
}

function currentSessionMeta() {
  const title = selectedRowTitle()
  const meta = title ? sessionMetaStore.getSnapshot().map.get(title) : undefined
  if (meta && typeof meta.cwd === 'string' && meta.cwd.length > 0) lastResolvedRoot = meta.cwd
  return { id: meta?.id ?? '', root: meta?.cwd ?? lastResolvedRoot }
}

// ── 标签注入 ────────────────────────────────────────────────────────────
// 新版 DSH 每条消息尾部已有原生“产出文件”行：本标签页默认关闭（设置卡 superseded.sessionFiles 开启）。
function ensureFileTab() {
  if (!wishadelSuperseded('sessionFiles')) {
    document.querySelectorAll('.wsh-session-files-tab').forEach((tab) => tab.remove())
    return
  }
  const tablist = document.querySelector('[role="tablist"]')
  if (!tablist) return
  let tab = tablist.querySelector('.wsh-session-files-tab')
  if (!tab) {
    tab = document.createElement('button')
    tab.type = 'button'
    tab.className = 'wsh-session-files-tab'
    tab.setAttribute('role', 'tab')
    tab.textContent = '文件'
    tab.addEventListener('click', (event) => {
      event.stopPropagation()
      if (filesUi.getSnapshot().open) filesUi.close()
      else filesUi.open()
    })
    tablist.appendChild(tab)
  }
  tab.setAttribute('aria-selected', filesUi.getSnapshot().open ? 'true' : 'false')
}

function installFileTabWatch(ctx) {
  let timer = null
  const schedule = () => {
    if (timer !== null) return
    timer = setTimeout(() => { timer = null; ensureFileTab() }, 120)
  }
  const onDocClick = (event) => {
    // 点击宿主「对话/轨迹」标签时关闭文件视图
    const tab = event.target instanceof Element ? event.target.closest('[role="tab"]') : null
    if (tab && !tab.classList.contains('wsh-session-files-tab')) filesUi.close()
  }
  document.addEventListener('click', onDocClick, true)
  const observer = new MutationObserver(schedule)
  observer.observe(document.body, { childList: true, subtree: true })
  schedule()
  // 设置变化时即时注入/移除「文件」标签。
  const unsubscribeSettings = runtimeRefs.settings?.subscribe?.(() => schedule()) ?? null
  const unsubscribe = filesUi.subscribe(() => schedule())
  ctx.effect(() => () => {
    observer.disconnect()
    if (unsubscribeSettings) unsubscribeSettings()
    unsubscribe()
    document.removeEventListener('click', onDocClick, true)
    if (timer !== null) clearTimeout(timer)
    document.querySelectorAll('.wsh-session-files-tab').forEach((tab) => tab.remove())
  }, 'wishadel: session files tab')
}

// ── 文件视图 ────────────────────────────────────────────────────────────
const KIND_LABEL = { modified: 'M', added: 'A', deleted: 'D', renamed: 'R' }

function SessionFilesView() {
  const open = useExternal(filesUi, (state) => state.open)
  const enabled = useExternal(runtimeRefs.settings, (state) => state?.superseded?.sessionFiles === true)
  const metaReady = useExternal(sessionMetaStore, (state) => state.ready)
  const viewRef = React.useRef(null)
  const [state, setState] = React.useState({ loading: false, files: [], isRepo: true, branch: '', error: null, message: null, detailPath: null, detailDiff: '', detailBusy: false })

  const load = React.useCallback(async () => {
    const meta = currentSessionMeta()
    if (!meta.root) {
      setState((prev) => ({ ...prev, loading: false, files: [], error: '未定位到会话工作区（侧栏选中行无 cwd）' }))
      return
    }
    setState((prev) => ({ ...prev, loading: true, error: null }))
    try {
      const data = await api('GET', '/session-files', undefined, { root: meta.root, sessionId: meta.id })
      setState((prev) => ({ ...prev, loading: false, files: data.files ?? [], isRepo: data.isRepo !== false, branch: data.branch ?? '', error: null, detailPath: null, detailDiff: '' }))
    } catch (cause) {
      setState((prev) => ({ ...prev, loading: false, error: String(cause?.message ?? cause) }))
    }
  }, [])

  // 打开/会话就绪时加载 + 位置同步
  React.useLayoutEffect(() => {
    if (!open || !metaReady) return
    load()
    const update = () => {
      const view = viewRef.current
      if (!view) return
      const sc = document.querySelector('[data-conversation-scroll]')
      if (!sc) { view.style.display = 'none'; return }
      const rect = sc.getBoundingClientRect()
      view.style.display = 'block'
      view.style.left = rect.left + 'px'
      view.style.top = rect.top + 'px'
      view.style.width = rect.width + 'px'
      view.style.height = rect.height + 'px'
    }
    update()
    document.addEventListener('scroll', update, { passive: true, capture: true })
    window.addEventListener('resize', update)
    const interval = setInterval(update, 400)
    return () => {
      document.removeEventListener('scroll', update, { passive: true, capture: true })
      window.removeEventListener('resize', update)
      clearInterval(interval)
    }
  }, [open, metaReady, load])

  if (!open || !enabled) return null

  const showDiff = async (file) => {
    const repo = file.repo ?? currentSessionMeta().root
    if (!repo) return
    setState((prev) => ({ ...prev, detailPath: file.path, detailBusy: true }))
    try {
      const diff = await api('GET', '/git/diff', undefined, { root: repo, path: file.repoPath ?? file.path, staged: file.staged ? '1' : '0' })
      const text = diff?.text ?? diff?.error ?? ''
      setState((prev) => ({ ...prev, detailDiff: text || '(无差异文本)', detailBusy: false }))
    } catch (cause) {
      setState((prev) => ({ ...prev, detailDiff: String(cause?.message ?? cause), detailBusy: false }))
    }
  }

  const acceptFile = async (file) => {
    const meta = currentSessionMeta()
    if (!meta.root) return
    try {
      await api('POST', '/file-accept', { root: meta.root, repo: file.repo, sessionId: meta.id, path: file.repoPath ?? file.path })
      setState((prev) => ({ ...prev, message: `已认可 ${file.path}`, files: prev.files.filter((f) => f.path !== file.path) }))
    } catch (cause) {
      setState((prev) => ({ ...prev, message: `认可失败：${cause?.message ?? cause}` }))
    }
  }

  const revertFile = async (file) => {
    const meta = currentSessionMeta()
    if (!meta.root) return
    try {
      const result = await api('POST', '/file-revert', { root: meta.root, repo: file.repo, path: file.repoPath ?? file.path })
      if (result?.ok) {
        setState((prev) => ({ ...prev, message: `已还原 ${file.path}`, files: prev.files.filter((f) => f.path !== file.path), detailPath: prev.detailPath === file.path ? null : prev.detailPath }))
      } else {
        setState((prev) => ({ ...prev, message: `还原失败：${result?.error ?? '未知错误'}` }))
      }
    } catch (cause) {
      setState((prev) => ({ ...prev, message: `还原失败：${cause?.message ?? cause}` }))
    }
  }

  const pending = state.files.filter((f) => !f.accepted)
  const acceptedCount = state.files.length - pending.length

  return React.createElement('div', { ref: viewRef, className: 'wsh-files-view wsh-surface', role: 'region', 'aria-label': '会话文件' },
    React.createElement('div', { className: 'wsh-files-head' },
      React.createElement('span', { className: 'wsh-files-title' }, `文件 FILES // ${state.branch || 'WORKTREE'}`),
      React.createElement('span', { className: 'wsh-files-count' }, `${pending.length} 待处理${acceptedCount > 0 ? ` · ${acceptedCount} 已认可` : ''}`),
      React.createElement('span', { className: 'wsh-spacer' }),
      state.message ? React.createElement('span', { className: 'wsh-hint', style: { color: 'var(--w-cyan)' } }, state.message) : null,
      React.createElement('button', { type: 'button', className: 'wsh-btn mini', onClick: load }, '刷新'),
      React.createElement('button', { type: 'button', className: 'wsh-btn mini', onClick: () => filesUi.close() }, '关闭')),
    state.error ? React.createElement('div', { className: 'wsh-hint', style: { padding: '10px 14px', color: 'var(--w-red-hot)' } }, state.error) : null,
    !state.error && !state.isRepo ? React.createElement('div', { className: 'wsh-hint', style: { padding: '10px 14px' } }, '当前工作区不是 Git 仓库，无法追踪文件变更。') : null,
    !state.error && state.isRepo && state.loading ? React.createElement('div', { className: 'wsh-hint', style: { padding: '10px 14px' } }, '加载中…') : null,
    !state.error && state.isRepo && !state.loading && pending.length === 0 && acceptedCount === 0
      ? React.createElement('div', { className: 'wsh-hint', style: { padding: '10px 14px' } }, '工作区干净，本会话暂无文件变更。')
      : null,
    React.createElement('div', { className: 'wsh-files-list' },
      pending.map((file) => React.createElement('div', { key: file.path, className: 'wsh-file-row' + (state.detailPath === file.path ? ' open' : '') },
        React.createElement('span', { className: `wsh-file-kind k-${file.kind}` }, KIND_LABEL[file.kind] ?? '?'),
        React.createElement('span', { className: 'wsh-file-path', title: file.path }, file.path),
        React.createElement('span', { className: 'wsh-file-actions' },
          React.createElement('button', { type: 'button', className: 'wsh-btn mini', onClick: () => showDiff(file) }, state.detailPath === file.path ? '收起' : '审查'),
          React.createElement('button', { type: 'button', className: 'wsh-btn mini', onClick: () => revertFile(file), title: '丢弃该文件的改动' }, '还原'),
          React.createElement('button', { type: 'button', className: 'wsh-btn mini primary', onClick: () => acceptFile(file), title: '标记为已认可' }, '认可')),
        state.detailPath === file.path
          ? React.createElement('pre', { className: 'wsh-file-diff' }, state.detailBusy ? '加载 diff…' : state.detailDiff)
          : null)),
      acceptedCount > 0 ? React.createElement('div', { className: 'wsh-hint', style: { padding: '8px 14px' } }, `${acceptedCount} 个文件已认可（改动再次变化时会重新出现）`) : null))
}

function installSessionFiles(ctx) {
  const slots = ctx.get('slots')
  installFileTabWatch(ctx)
  refreshSessionMeta()
  const metaTimer = setInterval(() => refreshSessionMeta(), 30000)
  if (slots !== undefined) {
    ctx.effect(() => slots.inject('shell.overlay', () => slots.register({
      name: 'shell.overlay',
      id: 'wishadel-session-files',
      order: 50,
      label: '会话文件',
    }, SessionFilesView)), 'wishadel: session files view')
  }
  ctx.effect(() => () => clearInterval(metaTimer), 'wishadel: session files meta timer')
}
